message.content:
{
  "title": "The Mirror Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The cartographer finds the lamp.",
      "visual_description": "Mara the Cartographer kneels beside a cracked fountain in the ruined plaza, holding up an oil lamp with one glowing eye that flickers awake.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "Fox scout reports a clear path.",
      "visual_description": "The Tin Fox scurries over rubble, its blue glass eyes scanning the broken streets, then stops and turns its head toward Mara.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The glass diver joins them at the gate.",
      "visual_description": "The Glass Diver emerges from a shattered shop window, his clear helmet reflecting the orange sunset, stepping onto the cobblestones.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Oracle warns of a cursed bell tower.",
      "visual_description": "The Oracle Lamp's flame flares up, casting long shadows as it speaks, pointing its glow toward a twisted spire in the distance.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "They find the sleeping tax collector.",
      "visual_description": "Under a collapsed archway, the Sleeping Tax Collector dozes, his head resting on a ledger book, papers stuck to his coat sleeves.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Fox sniffs a hidden passage behind a tapestry.",
      "visual_description": "The Tin Fox noses at a frayed royal banner hanging from a wall, revealing a narrow stone passage behind it.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "Mara draws a new route on her map.",
      "visual_description": "Mara kneels, unrolling her stained map and inking a fresh line through the ruins while the Oracle Lamp hovers nearby.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The glass diver swims through a magic door.",
      "visual_description": "The Glass Diver presses his helmet against a shimmering door of light, then steps through its surface as if through water.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "They discover a room full of forgotten taxes.",
      "visual_description": "The Sleeping Tax Collector stirs as they enter a chamber stacked with dusty scrolls and coin chests, his ledger slips from his hand.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Armored patrols clank through the street above.",
      "visual_description": "Through a grate, they see the metal boots of patrols marching past, their armor reflecting torchlight.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Fox leads them past a collapsed temple.",
      "visual_description": "The Tin Fox darts around fallen columns, its key-wind tail ticking, guiding the group through the debris.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "The lamp warns of a trap ahead.",
      "visual_description": "The Oracle Lamp's eye narrows as it glares at a doorway etched with runes, the flame hissing a warning.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The glass diver disarms the rune trap.",
      "visual_description": "The Glass Diver reaches into a mirror shard, his arm disappearing, and the runes fade as he twists something unseen.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "They climb a spiral staircase in a tower.",
      "visual_description": "The group ascends a narrow spiral staircase, the Oracle Lamp casting dancing shadows on the curved stone walls.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "From the tower, they spot the bridge escape.",
      "visual_description": "At the top of the tower, Mara points across the ruined city to a stone bridge spanning a dry riverbed.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Patrols close in from two streets.",
      "visual_description": "Below, armored patrols converge on the base of the tower, their footsteps echoing in unison.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The glass diver creates a mirrored path downward.",
      "visual_description": "The Glass Diver smashes a window, and pieces of glass form a reflective staircase leading to the street.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "They cross the bridge to safety.",
      "visual_description": "The group sprints across the stone bridge as the Oracle Lamp's flame burns low, the city ruins behind them fading into mist.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

